class Order {
  items: string[];
  total: number;
  constructor(items: string[]) { this.items = items; this.total = items.length * 10 }
}
function applyDiscount(order: Order, discount: number) {
  order.total = order.total - discount;
}

type Product = { id: string; stock: number };
const products: Product[] = [{ id: "p1", stock: 10 }];
function decrementStock(productId: string, amount: number) {
  const p = products.find(p => p.id === productId);
  if (!p) return;
  p.stock -= amount;
}
function getProduct(productId: string) { return products.find(p => p.id === productId); }

// Version A: returns new objects rather than mutating inputs
function addItemA(order: Readonly<Order>, item: string): Order {
  return { ...order, items: [...order.items, item], total: order.total + itemPrice(item) };
}

// Version B: mutates the order in place and returns it
function addItemB(order: Order, item: string): Order {
  order.items.push(item);
  order.total += itemPrice(item);
  return order;
}
